           Dark analytical theme for AI safety research
           =========================================== */
        :root {
            --bg-primary: #0c0f14;
            --bg-secondary: #141820;
            --bg-tertiary: #1a2028;
            --text-primary: #f0f2f5;
            --text-secondary: #8b929e;
            --text-muted: #5a6270;
            --accent: #00d4aa;
            --accent-secondary: #6366f1;
            --accent-glow: rgba(0, 212, 170, 0.25);
            --accent-secondary-glow: rgba(99, 102, 241, 0.25);
            --border: rgba(255, 255, 255, 0.08);
            --chart-line: #00d4aa;
            --chart-grid: rgba(255, 255, 255, 0.06);

            --font-display: 'Clash Display', sans-serif;
            --font-body: 'Satoshi', sans-serif;
            --title-size: clamp(1.75rem, 5vw, 3.5rem);
            --h2-size: clamp(1.25rem, 3vw, 2rem);
            --h3-size: clamp(1rem, 2vw, 1.5rem);
            --body-size: clamp(0.8rem, 1.3vw, 1.1rem);
            --small-size: clamp(0.7rem, 1vw, 0.9rem);
            --caption-size: clamp(0.6rem, 0.9vw, 0.8rem);

            --slide-padding: clamp(1.5rem, 4vw, 4rem);
            --content-gap: clamp(0.75rem, 2vw, 1.5rem);
            --element-gap: clamp(0.4rem, 1vw, 0.8rem);

            --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
            --duration-normal: 0.6s;
        }

        /* ===========================================
           BASE STYLES
           =========================================== */
        * { margin: 0; padding: 0; box-sizing: border-box; }

        html {
            scroll-snap-type: y mandatory;
            scroll-behavior: smooth;
        }

        body {
            font-family: var(--font-body);
            background: var(--bg-primary);
            color: var(--text-primary);
            line-height: 1.5;
            overflow-x: hidden;
        }

        /* ===========================================
           SLIDE LAYOUT
           =========================================== */
        .slide {
            width: 100vw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
            background: var(--bg-primary);
        }

        .slide-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: center;
            max-height: 100%;
            overflow: hidden;
            padding: var(--slide-padding);
        }

        /* ===========================================
           TYPOGRAPHY
           =========================================== */
        h1 {
            font-family: var(--font-display);
            font-size: var(--title-size);
            font-weight: 700;
            line-height: 1.1;
            letter-spacing: -0.02em;
        }

        h2 {
            font-family: var(--font-display);
            font-size: var(--h2-size);
            font-weight: 600;
            line-height: 1.2;
            margin-bottom: var(--content-gap);
        }

        h3 {
            font-family: var(--font-body);
            font-size: var(--h3-size);
            font-weight: 600;
            line-height: 1.3;
        }

        p, li {
            font-size: var(--body-size);
            color: var(--text-secondary);
        }

        /* ===========================================
           TITLE SLIDE
           =========================================== */
        .title-slide {
            background:
                radial-gradient(ellipse at 30% 70%, rgba(0, 212, 170, 0.08) 0%, transparent 50%),
                radial-gradient(ellipse at 80% 20%, rgba(99, 102, 241, 0.06) 0%, transparent 40%),
                var(--bg-primary);
        }

        .title-slide .slide-content {
            align-items: center;
            text-align: center;
            gap: var(--content-gap);
        }

        .title-slide h1 {
            max-width: 900px;
        }

        .headline-badge {
            display: inline-block;
            background: linear-gradient(135deg, var(--accent), var(--accent-secondary));
            color: var(--bg-primary);
            font-size: var(--small-size);
            font-weight: 700;
            padding: clamp(0.4rem, 0.8vw, 0.6rem) clamp(0.8rem, 1.5vw, 1.2rem);
            border-radius: 100px;
            margin-bottom: var(--element-gap);
        }

        .subtitle {
            font-size: var(--h3-size);
            color: var(--text-secondary);
            max-width: 700px;
        }

        .meta-info {
            display: flex;
            gap: var(--content-gap);
            font-size: var(--caption-size);
            color: var(--text-muted);
            margin-top: var(--element-gap);
        }

        .meta-info span {
            display: flex;
            align-items: center;
            gap: 0.4rem;
        }

        /* ===========================================
           METRIC EXPLAINED SLIDE
           =========================================== */
        .metric-flow {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: var(--content-gap);
            max-width: 1100px;
            margin: 0 auto;
        }

        .flow-step {
            background: var(--bg-secondary);
            border: 1px solid var(--border);
            border-radius: 12px;
            padding: clamp(1rem, 2vw, 1.5rem);
            text-align: center;
            position: relative;
        }

        .flow-step::after {
            content: '→';
            position: absolute;
            right: -0.6em;
            top: 50%;
            transform: translateY(-50%);
            color: var(--accent);
            font-size: 1.5em;
            opacity: 0.6;
        }

        .flow-step:last-child::after {
            display: none;
        }

        .step-number {
            width: clamp(2rem, 3vw, 2.5rem);
            height: clamp(2rem, 3vw, 2.5rem);
            background: var(--accent);
            color: var(--bg-primary);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: 700;
            font-size: var(--body-size);
            margin: 0 auto var(--element-gap);
        }

        .flow-step h3 {
            margin-bottom: var(--element-gap);
            color: var(--text-primary);
        }

        .flow-step p {
            font-size: var(--small-size);
        }

        .formula-highlight {
            background: var(--bg-tertiary);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: var(--element-gap) clamp(0.8rem, 1.5vw, 1.2rem);
            font-family: monospace;
            font-size: var(--small-size);
            color: var(--accent);
            text-align: center;
            margin-top: var(--content-gap);
            max-width: 500px;
            margin-left: auto;
            margin-right: auto;
        }

        .methodology-image {
            max-width: 100%;
            max-height: min(35vh, 280px);
            object-fit: contain;
            border-radius: 8px;
            margin-top: var(--element-gap);
            border: 1px solid var(--border);
        }

        /* ===========================================
           TASK SUITE TABLE
           =========================================== */
        .table-container {
            overflow-x: auto;
            max-width: 100%;
        }

        table {
            width: 100%;
            border-collapse: collapse;
            font-size: var(--small-size);
        }

        th {
            background: var(--bg-tertiary);
            color: var(--text-primary);
            font-weight: 600;
            text-align: left;
            padding: clamp(0.5rem, 1vw, 0.75rem) clamp(0.6rem, 1.2vw, 1rem);
            border-bottom: 2px solid var(--accent);
        }

        td {
            padding: clamp(0.4rem, 0.8vw, 0.6rem) clamp(0.6rem, 1.2vw, 1rem);
            border-bottom: 1px solid var(--border);
            color: var(--text-secondary);
        }

        tr:hover td {
            background: rgba(0, 212, 170, 0.05);
        }

        .suite-cards {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: var(--content-gap);
            margin-bottom: var(--content-gap);
        }

        .suite-card {
            background: var(--bg-secondary);
            border: 1px solid var(--border);
            border-radius: 10px;
            padding: clamp(0.8rem, 1.5vw, 1.2rem);
            text-align: center;
        }

        .suite-card .count {
            font-size: var(--h2-size);
            font-weight: 700;
            color: var(--accent);
            display: block;
        }

        .suite-card .name {
            font-size: var(--body-size);
            color: var(--text-primary);
            font-weight: 600;
            margin-bottom: 0.25rem;
        }

        .suite-card .range {
            font-size: var(--caption-size);
            color: var(--text-muted);
        }

        /* ===========================================
           EXPONENTIAL TREND CHART
           =========================================== */
        .chart-container {
            position: relative;
            width: 100%;
            max-width: 900px;
            margin: 0 auto;
        }

        .chart-image {
            width: 100%;
            max-height: min(45vh, 380px);
            object-fit: contain;
            border-radius: 10px;
            border: 1px solid var(--border);
