cat > /tmp/capture_slides.cjs << 'SCRIPT'
const { chromium } = require('playwright');

(async () => {
    const browser = await chromium.launch();
    const page = await browser.newPage();
    await page.setViewportSize({ width: 1920, height: 1080 });

    const htmlPath = '/app/output/presentation.html';
    await page.goto('file://' + htmlPath, { waitUntil: 'networkidle' });

    // Wait for content to load
    await page.waitForTimeout(1000);

    // Count slides
    const slideCount = await page.$$eval('.slide', els => els.length);
    console.log('Found', slideCount, 'slides');

    const outDir = '/tmp/slides';
    const fs = require('fs');
    if (!fs.existsSync(outDir)) fs.mkdirSync(outDir);

    // Capture each slide by scrolling to it
    for (let i = 0; i < slideCount; i++) {
        console.log('Capturing slide', i + 1);
        await page.evaluate((idx) => {
            window.scrollTo({ top: idx * window.innerHeight, left: 0 });
        }, i);
        await page.waitForTimeout(800); // Wait for animations

        const idx = String(i + 1).padStart(3, '0');
        await page.screenshot({ path: `${outDir}/slide_${idx}.png` });
    }

    console.log('Done capturing');
    await browser.close();
})();
